@Component
public class CustomServiceRegistration implements RuntimeHintsRegistrar {
    @Override
    public void registerHints(RuntimeHints hints, ClassLoader classLoader) {
        // Explicitly register reflection for native image compatibility
        hints.reflection().registerType(
            SecurePayload.class,
            MemberCategory.INVOCABLE_PUBLIC_METHODS,
            MemberCategory.ACCESS_PUBLIC_FIELDS
        );

        // Register resources needed at runtime
        hints.resources().registerPattern("templates/*.html");
    }
}
